// Cross-runtime vectors generated by testdata/gen-vectors.js from the Node
// core's dist build (see the script header).

type nodeVector struct {
	Name      string            `json:"name"`
	Profile   string            `json:"profile"`
	Responses []json.RawMessage `json:"responses"`
	Requests  []recorded        `json:"requests"`
	Result    json.RawMessage   `json:"result"`
	Error     *struct {
		Status  int    `json:"status"`
		Message string `json:"message"`
	} `json:"error"`
}

type nodeVectors struct {
	Vectors []nodeVector `json:"vectors"`
	Tokens  []struct {
		Name  string         `json:"name"`
		Opts  map[string]any `json:"opts"`
		Token string         `json:"token"`
	} `json:"tokens"`
	BadTTL []struct {
		TTL   string `json:"ttl"`
		Error string `json:"error"`
	} `json:"badTtl"`
	Scrypt []struct{ Password, Salt, Hash string } `json:"scrypt"`
	Hint   []struct {
		Raw *string `json:"raw"`
		Out string  `json:"out"`
	} `json:"hint"`
	Webhook struct{ Body, Auth string } `json:"webhook"`
}

func loadVectors(t *testing.T) nodeVectors {
	t.Helper()
	b, err := os.ReadFile("testdata/node_vectors.json")
	if err != nil {
		t.Fatal(err)
	}
	var v nodeVectors
	if err := json.Unmarshal(b, &v); err != nil {
		t.Fatal(err)
	}
	return v
}

func generic(t *testing.T, b []byte) any {
	t.Helper()
	var v any
	if err := json.Unmarshal(b, &v); err != nil {
		t.Fatalf("bad json %s: %v", b, err)
	}
	return v
}

func fptr(f float64) *float64 { return &f }
func bptr(b bool) *bool       { return &b }

// goCall runs the Go counterpart of one vector.
func goCall(ctx context.Context, s *Service, name string) (any, error) {
	base := CreateIngressInput{AppName: "live", RoomName: "live-ch1", ParticipantIdentity: "ingress-live", ParticipantName: "Cam"}
	ing := func(mod func(*CreateIngressInput)) (any, error) {
		in := base
		mod(&in)
		return s.CreateIngress(ctx, in)
	}
	name = strings.TrimSuffix(strings.TrimSuffix(name, "-livekit"), "-efficient")
	none := func(err error) (any, error) { return nil, err }
	switch name {
	case "ingress-rtmp":
		return ing(func(i *CreateIngressInput) { i.InputType, i.EnableTranscoding = "rtmp", bptr(true) })
	case "ingress-rtmp-bypass":
		return ing(func(i *CreateIngressInput) { i.InputType, i.EnableTranscoding = "rtmp", bptr(false) })
	case "ingress-whip-bypass":
		return ing(func(i *CreateIngressInput) { i.InputType, i.EnableTranscoding = "whip", bptr(false) })
	case "ingress-whip-on":
		return ing(func(i *CreateIngressInput) { i.InputType, i.EnableTranscoding = "whip", bptr(true) })
	case "ingress-url":
		return ing(func(i *CreateIngressInput) { i.InputType, i.URL = "url", "rtsp://93.184.216.34/cam" })
	case "ingress-1080":
		return ing(func(i *CreateIngressInput) { i.InputType, i.MaxHeight = "rtmp", fptr(1080) })
	case "ingress-480":
		return ing(func(i *CreateIngressInput) { i.InputType, i.MaxHeight = "rtmp", fptr(480) })
	case "ingress-adaptive":
		return ing(func(i *CreateIngressInput) { i.InputType, i.Simulcast = "rtmp", true })
	case "ingress-adaptive-1080":
		return ing(func(i *CreateIngressInput) {
			i.InputType, i.URL, i.Simulcast, i.MaxHeight = "url", "srt://93.184.216.34:9000", true, fptr(1080)
		})
	case "ingress-audio":
		return ing(func(i *CreateIngressInput) { i.InputType, i.AudioOnly = "rtmp", true })
	case "ingress-reject", "ingress-no-public-host":
		return ing(func(i *CreateIngressInput) { i.InputType = "rtmp" })
	case "ingress-list":
		return s.ListIngress(ctx, "")
	case "ingress-delete":
		return none(s.DeleteIngress(ctx, "IN_1"))
	case "egress-room-composite":
		return s.StartEgress(ctx, StartEgressInput{AppName: "live", RoomName: "live-ch1", Mode: "room-composite", Layout: "grid",
			OutputFilepath: "/data/rec/a.mp4", SnapshotIntervalS: 10.7, SnapshotFilePrefix: "/data/rec/snap_"})
	case "egress-participant":
		return s.StartEgress(ctx, StartEgressInput{AppName: "live", RoomName: "live-ch1", Mode: "participant", ParticipantIdentity: "u1", OutputFilepath: "/data/rec/b.mp4"})
	case "egress-participant-missing":
		return s.StartEgress(ctx, StartEgressInput{AppName: "live", RoomName: "live-ch1", Mode: "participant", OutputFilepath: "/x.mp4"})
	case "egress-track", "egress-track-none":
		return s.StartTrackCompositeEgress(ctx, TrackCompositeInput{AppName: "live", RoomName: "live-ch1", ParticipantIdentity: "u1", OutputFilepath: "/r.mp4"})
	case "egress-track-audio":
		return s.StartTrackCompositeEgress(ctx, TrackCompositeInput{AppName: "live", RoomName: "live-ch1", ParticipantIdentity: "u1", OutputFilepath: "/r.mp4", AudioOnly: true})
	case "egress-stream":
		return s.StartStreamEgress(ctx, StartStreamEgressInput{AppName: "live", RoomName: "live-ch1", RtmpURL: "rtmp://a.rtmp.youtube.com/live2/key", Layout: "speaker"})
	case "egress-hls":
		return s.StartHlsEgress(ctx, StartHlsEgressInput{AppName: "live", RoomName: "live-ch1", OutputDir: "/data/hls/live/ch1", PlaylistName: "index.m3u8", SegmentDurationS: 2.5})
	case "egress-hls-dvr":
		return s.StartHlsEgress(ctx, StartHlsEgressInput{AppName: "live", RoomName: "live-ch1", OutputDir: "/data/hls/x", PlaylistName: "index.m3u8", LivePlaylistName: "live.m3u8"})
	case "egress-list-hls":
		return s.ListHlsEgress(ctx, "live")
	case "egress-list-stream":
		return s.ListStreamEgress(ctx, "live")
	case "egress-stop":
		return s.StopEgress(ctx, "E1")
	case "egress-stop-fail":
		return s.StopEgress(ctx, "E9")
	case "room-create":
		return s.CreateRoom(ctx, "live-ch1", 86400)
	case "room-create-default":
		return s.CreateRoom(ctx, "live-ch2", 0)
	case "room-delete":
		return none(s.DeleteRoom(ctx, "live-ch1"))
	case "room-list":
		return s.ListRooms(ctx, nil)
	case "room-list-names":
		return s.ListRooms(ctx, []string{"live-ch1", "live-ch9"})
	case "room-list-detailed":
		return s.ListRoomsDetailed(ctx, nil)
	case "room-get", "room-get-missing":
		r, err := s.GetRoom(ctx, "live-ch1")
		if r == nil {
			return nil, err
		}
		return r, err
	case "room-metadata":
		return s.UpdateRoomMetadata(ctx, "live-ch1", `{"onAir":true}`)
	case "room-metadata-empty":
		return s.UpdateRoomMetadata(ctx, "live-ch1", "")
	case "participants":
		return s.ListParticipants(ctx, "live-ch1")
	case "participants-detailed":
		return s.ListParticipantsDetailed(ctx, "live-ch1")
	case "participant-get":
		return s.GetParticipant(ctx, "live-ch1", "u1")
	case "participant-remove":
		return none(s.RemoveParticipant(ctx, "live-ch1", "u1"))
	case "participant-mute":
		return s.MutePublishedTrack(ctx, "live-ch1", "u1", "TR_A", true)
	case "participant-mute-empty":
		return s.MutePublishedTrack(ctx, "live-ch1", "u1", "TR_A", false)
	case "participant-update":
		md, nm := "md", "New"
		return s.UpdateParticipant(ctx, "live-ch1", "u1", UpdateParticipantOptions{Metadata: &md, Name: &nm,
			Permission: &PermissionPatch{bptr(false), bptr(true), bptr(true), bptr(false)}})
	case "participant-update-meta":
		md := ""
		return s.UpdateParticipant(ctx, "live-ch1", "u1", UpdateParticipantOptions{Metadata: &md})
	case "participant-subscriptions":
		return none(s.UpdateSubscriptions(ctx, "live-ch1", "u1", []string{"TR_A", "TR_V"}, false))
	case "data-send":
		t := "chat"
		return none(s.SendData(ctx, "live-ch1", `{"topic":"chat"}`, SendDataOptions{Topic: &t, DestinationIdentities: []string{"u1"}}))
	case "data-send-lossy":
		t := ""
		return none(s.SendData(ctx, "live-ch1", "x", SendDataOptions{Topic: &t, Reliable: bptr(false)}))
	case "data-send-fail":
		t := "t"
		return none(s.SendData(ctx, "live-ch1", "x", SendDataOptions{Topic: &t}))
	}
	panic("no Go mapping for vector " + name)
}

func TestNodeRequestVectors(t *testing.T) {
	ctx := context.Background()
	for _, v := range loadVectors(t).Vectors {
		t.Run(v.Name, func(t *testing.T) {
			f := &fakeLK{}
			for _, r := range v.Responses {
				var probe any
				_ = json.Unmarshal(r, &probe)
				if m, ok := probe.(map[string]any); ok && len(m) == 0 {
					f.responses = append(f.responses, "{}")
					continue
				}
				// An `{}` Error object in JS serialises as {}; the generator
				// marks rejections by their position: see errorResponses.
				f.responses = append(f.responses, string(r))
			}
			markErrors(v, f)
			cfg := testConfig(v.Profile)
			if v.Name == "ingress-no-public-host" {
				cfg.RtmpPublicHost = ""
			}
			res, err := goCall(ctx, newTestService(cfg, f), v.Name)

			if len(f.requests) != len(v.Requests) {
				t.Fatalf("requests: go %d, node %d", len(f.requests), len(v.Requests))
			}
			for i, want := range v.Requests {
				got := f.requests[i]
				if got.Service != want.Service || got.Method != want.Method {
					t.Fatalf("request %d: go %s/%s node %s/%s", i, got.Service, got.Method, want.Service, want.Method)
				}
				if g, w := generic(t, got.Data), generic(t, want.Data); !reflect.DeepEqual(g, w) {
					t.Errorf("request %d %s:\n go   %s\n node %s", i, got.Method, got.Data, want.Data)
				}
			}
			if v.Error != nil {
				he, ok := errorsAs(err)
				if !ok || he.Status != v.Error.Status || he.Error() != v.Error.Message {
					t.Fatalf("error: go %v, node %d %q", err, v.Error.Status, v.Error.Message)
				}
				return
			}
			if err != nil {
				t.Fatalf("unexpected error %v", err)
			}
			got, _ := json.Marshal(res)
			if string(got) == "null" && string(v.Result) == "null" {
				return
			}
			if g, w := generic(t, got), generic(t, v.Result); !reflect.DeepEqual(g, w) {
				t.Errorf("result:\n go   %s\n node %s", got, v.Result)
			}
		})
	}
}

// markErrors turns the generator's rejected responses (JS Error objects
// serialise as {}) back into failures, by vector.
func markErrors(v nodeVector, f *fakeLK) {
	switch {
	case strings.HasPrefix(v.Name, "ingress-reject"):
		f.responses[0] = "!error:invalid preset"
	case v.Name == "egress-stop-fail":
		f.responses[0] = "!error:egress not found"
	case v.Name == "data-send-fail":
		f.responses[0] = "!error:room not found"
	}
}

func TestNodeTokens(t *testing.T) {
	v := loadVectors(t)
	for _, tc := range v.Tokens {
		t.Run(tc.Name, func(t *testing.T) {
			parts := strings.Split(tc.Token, ".")
			raw, _ := base64.RawURLEncoding.DecodeString(parts[1])
			var claims struct {
				Nbf int64 `json:"nbf"`
			}
			_ = json.Unmarshal(raw, &claims)
			b, _ := json.Marshal(tc.Opts)
			var in struct {
				Room, Identity, Name, TTL, Metadata      string
				CanPublish, CanSubscribe, CanPublishData *bool
				Hidden, Recorder, AudioOnly              bool
			}
			_ = json.Unmarshal(b, &in)
			o := MintTokenOptions{Room: in.Room, Identity: in.Identity, Name: in.Name, TTL: in.TTL, Metadata: in.Metadata,
				CanPublish: in.CanPublish, CanSubscribe: in.CanSubscribe, CanPublishData: in.CanPublishData,
				Hidden: in.Hidden, Recorder: in.Recorder, AudioOnly: in.AudioOnly}
			got, err := signToken("APIkey", "secret-0123456789", o, time.Unix(claims.Nbf, 0))
			if err != nil {
				t.Fatal(err)
			}
			if got != tc.Token {
				gp, _ := base64.RawURLEncoding.DecodeString(strings.Split(got, ".")[1])
				t.Fatalf("token bytes differ:\n go   %s\n node %s", gp, raw)
			}
			// LiveKit server 1.13 (protocol/auth) accepts the grant.
			pv, err := lkauth.ParseAPIToken(got)
			if err != nil {
				t.Fatal(err)
			}
			if pv.APIKey() != "APIkey" || pv.Identity() != in.Identity {
				t.Fatalf("iss/sub: %s %s", pv.APIKey(), pv.Identity())
			}
			// (no Verify: the vector tokens expire after generation; the
			// grant round-trip is TestTokenGrantsParseInProtocol)
		})
	}
	for _, bt := range v.BadTTL {
		s := newTestService(testConfig("livekit"), &fakeLK{})
		_, err := s.MintToken(MintTokenOptions{Room: "r", Identity: "i", TTL: bt.TTL})
		if he, ok := errorsAs(err); !ok || he.Error() != bt.Error || he.Status != 503 {
			t.Errorf("ttl %q: go %v, node %q", bt.TTL, err, bt.Error)
		}
	}
}

func TestTokenGrantsParseInProtocol(t *testing.T) {
	tok, err := signToken("APIkey", "secret-0123456789", MintTokenOptions{
		Room: "live-radio", Identity: "host", CanPublish: bptr(true), AudioOnly: true, Hidden: true, Recorder: true,
		Name: "Host", Metadata: "md",
	}, time.Now())
	if err != nil {
		t.Fatal(err)
	}
	pv, err := lkauth.ParseAPIToken(tok)
	if err != nil {
		t.Fatal(err)
	}
	_, g, err := pv.Verify("secret-0123456789")
	if err != nil {
		t.Fatal(err)
	}
	vg := g.Video
	if !vg.RoomJoin || vg.Room != "live-radio" || !vg.GetCanPublish() || !vg.GetCanSubscribe() || !vg.GetCanPublishData() ||
		!vg.Hidden || !vg.RoomRecord || len(vg.CanPublishSources) != 1 || vg.CanPublishSources[0] != "microphone" {
		t.Fatalf("grants %+v", vg)
	}
	if g.Name != "Host" || g.Metadata != "md" || g.Identity != "host" {
		t.Fatalf("claims %+v", g)
	}
}

func TestNodeScryptHashes(t *testing.T) {
	for _, v := range loadVectors(t).Scrypt {
		if got := hashPassword(v.Password, v.Salt); got != v.Hash {
			t.Errorf("scrypt(%q,%q) = %s, node %s", v.Password, v.Salt, got, v.Hash)
		}
	}
}

func TestNodeSimulcastHint(t *testing.T) {
	cfg := &contracts.AppConfig{}
	cfg.Webrtc.Layers = []contracts.WebrtcLayer{{Name: "low", Height: 360}, {Name: "high", Height: 720}}
	for _, h := range loadVectors(t).Hint {
		if got := withSimulcastHint(h.Raw, cfg); got != h.Out {
			t.Errorf("hint(%v):\n go   %s\n node %s", h.Raw, got, h.Out)
		}
	}
}

func TestNodeSignedWebhookVerifies(t *testing.T) {
	v := loadVectors(t).Webhook
	s := newTestService(testConfig("livekit"), &fakeLK{})
	ev, err := s.ReceiveWebhook([]byte(v.Body), v.Auth)
	if err != nil {
		t.Fatal(err)
	}
	if ev.GetEvent() != "track_published" || ev.GetRoom().GetName() != "live-ch1" || ev.GetParticipant().GetIdentity() != "u1" {
		t.Fatalf("event %v", ev)
	}
	// One flipped body byte breaks the sha256 claim; a wrong secret the HMAC.
	if _, err := s.ReceiveWebhook([]byte(strings.Replace(v.Body, "u1", "u2", 1)), v.Auth); err == nil ||
		err.Error() != "sha256 checksum of body does not match" {
		t.Fatalf("tampered body: %v", err)
	}
	other := testConfig("livekit")
	other.LivekitAPISecret = "nope"
	if _, err := newTestService(other, &fakeLK{}).ReceiveWebhook([]byte(v.Body), v.Auth); err == nil {
		t.Fatal("wrong secret accepted")
	}
	if _, err := s.ReceiveWebhook([]byte(v.Body), ""); err == nil || err.Error() != "authorization header is empty" {
		t.Fatalf("empty auth: %v", err)
	}
}
